// Package chartimage renders the shared Analysis plot without a desktop window
// or market-data subscription. It only accepts already-prepared closed bars.
package chartimage

import (
	"bytes"
	"context"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"image/png"
	"io"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"time"

	"cryptodesk/internal/screener"
)

// The worker is tracked; chart.js/css are generated by the frontend build.
// Embedding the directory also permits Go tests and binding generation before
// that build on a fresh checkout. Production builds generate all three files.
//
//go:embed assets
var assets embed.FS

const (
	maxInput      = 2 << 20
	maxImage      = 8 << 20
	renderTimeout = 20 * time.Second
)

// Runtime comes exclusively from the application's verified Screener runtime.
// It is never deserialized from an alert, workspace, or chart payload.
type Runtime struct{ Node, Directory, Browser string }

type Request struct {
	Chart     *screener.AnalysisChart `json:"chart"`
	Title     string                  `json:"title"`
	Source    string                  `json:"source"`
	Market    string                  `json:"market"`
	Condition string                  `json:"condition"`
	Theme     string                  `json:"theme,omitempty"`
	FontSize  int                     `json:"fontSize,omitempty"`
}

// Renderer bounds Chromium to one process tree, including concurrent alert
// checks. Its deadline includes queueing so stale signals cannot pile up.
type Renderer struct{ gate, pending chan struct{} }

func New() *Renderer { return &Renderer{gate: make(chan struct{}, 1), pending: make(chan struct{}, 8)} }

func (r *Renderer) Render(ctx context.Context, runtime Runtime, request Request) ([]byte, error) {
	ctx, cancel := context.WithTimeout(ctx, renderTimeout)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	// At most one render plus seven queued snapshots retain JSON and wait.
	select {
	case r.pending <- struct{}{}:
		defer func() { <-r.pending }()
	default:
		return nil, errors.New("signal chart renderer is busy")
	}
	if err := validate(request); err != nil {
		return nil, err
	}
	payload, err := json.Marshal(request)
	if err != nil || len(payload) > maxInput {
		return nil, errors.New("signal chart snapshot is too large or invalid")
	}
	select {
	case r.gate <- struct{}{}:
		defer func() { <-r.gate }()
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	for _, path := range []string{runtime.Node, runtime.Browser, runtime.Directory} {
		if !filepath.IsAbs(path) {
			return nil, errors.New("signal chart runtime is unavailable")
		}
	}
	for _, path := range []string{runtime.Node, runtime.Browser} {
		if info, e := os.Stat(path); e != nil || !info.Mode().IsRegular() {
			return nil, errors.New("signal chart runtime is unavailable")
		}
	}
	files := make(map[string][]byte, 3)
	for _, name := range []string{"worker.cjs", "chart.js", "chart.css"} {
		files[name], err = assets.ReadFile("assets/" + name)
		if err != nil {
			return nil, errors.New("signal chart assets are unavailable; rebuild the frontend and application")
		}
	}
	directory, err := privateDirectory()
	if err != nil {
		return nil, errors.New("cannot prepare signal chart renderer")
	}
	defer os.RemoveAll(directory)
	for name, contents := range files {
		if err = os.WriteFile(filepath.Join(directory, name), contents, 0600); err != nil {
			return nil, errors.New("cannot prepare signal chart renderer")
		}
	}
	cmd := exec.CommandContext(ctx, runtime.Node, filepath.Join(directory, "worker.cjs"), runtime.Directory, runtime.Browser)
	cmd.Dir = directory
	cmd.Env = renderEnvironment(directory)
	cmd.Stdin = bytes.NewReader(payload)
	output, diagnostics := &limitedBuffer{max: maxImage}, &limitedBuffer{max: 4096}
	cmd.Stdout, cmd.Stderr = output, diagnostics
	cmd.WaitDelay = time.Second
	configureProcess(cmd)
	if err = cmd.Run(); err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		// Worker diagnostics contain no request data, and are deliberately kept
		// out of notification text and logs to avoid exposing local file paths.
		return nil, errors.New("signal chart rendering failed")
	}
	image := output.Bytes()
	config, err := png.DecodeConfig(bytes.NewReader(image))
	if err != nil || config.Width < 1 || config.Height < 1 || config.Width+config.Height > 10000 || float64(config.Width)/float64(config.Height) > 20 || float64(config.Height)/float64(config.Width) > 20 {
		return nil, errors.New("signal chart image has invalid dimensions")
	}
	return image, nil
}

func validate(request Request) error {
	c := request.Chart
	if c == nil || len(c.Bars) == 0 || len(c.Bars) > 121 || len(c.Fields) > 64 || c.MatchTime <= 0 || len(request.Title) > 512 || len(request.Condition) > 4096 || len(request.Source) > 64 || len(request.Market) > 64 {
		return errors.New("signal chart snapshot is invalid")
	}
	// encoding/json escapes a string byte into at most six ASCII bytes. Count
	// repeated map keys before marshaling so imported field names cannot cause
	// a large allocation even when bars/fields are individually bounded.
	remaining := maxInput - 8192 // structural keys, levels and fixed metadata
	consume := func(value string) bool {
		if len(value) > remaining/6 {
			return false
		}
		remaining -= len(value) * 6
		return true
	}
	for _, value := range []string{request.Title, request.Source, request.Market, request.Condition, request.Theme, c.ResultID, c.Name, c.Symbol, c.Timeframe} {
		if !consume(value) {
			return errors.New("signal chart snapshot is too large")
		}
	}
	for _, field := range c.Fields {
		if !consume(field) {
			return errors.New("signal chart snapshot is too large")
		}
	}
	found := false
	var previous int64
	for i, bar := range c.Bars {
		if bar.Time <= 0 || bar.Time > c.MatchTime || (i > 0 && bar.Time <= previous) || len(bar.Values) > 64 {
			return errors.New("signal chart bars must be ordered closed bars")
		}
		previous = bar.Time
		if bar.Time == c.MatchTime {
			found = true
		}
		remaining -= 80 // bar index, timestamp, punctuation
		for field, value := range bar.Values {
			remaining -= 32 // number and punctuation
			if remaining < 0 || !consume(field) {
				return errors.New("signal chart snapshot is too large")
			}
			if math.IsNaN(value) || math.IsInf(value, 0) {
				return errors.New("signal chart values must be finite")
			}
		}
	}
	if !found {
		return errors.New("signal chart match is missing")
	}
	if c.Trade != nil || c.TradeExecution != nil || len(c.ProfitableMatches) != 0 {
		return errors.New("live signal chart cannot contain historical trade outcomes")
	}
	if c.Signal != nil {
		if !finite(c.Signal.Entry) || c.Signal.StopLoss != nil && !finite(*c.Signal.StopLoss) || c.Signal.TakeProfit != nil && !finite(*c.Signal.TakeProfit) {
			return errors.New("signal chart levels must be finite")
		}
	}
	return nil
}

func finite(value float64) bool { return !math.IsNaN(value) && !math.IsInf(value, 0) }

// Chromium's disposable profiles and caches belong to the same private tree,
// including when cancellation kills it before Playwright can clean up. Avoid
// inheriting API tokens or NODE_OPTIONS into the renderer subprocess.
func renderEnvironment(directory string) []string {
	var result []string
	for _, name := range []string{"PATH", "SystemRoot", "WINDIR", "SYSTEMDRIVE", "COMSPEC", "HOME", "USERPROFILE", "LANG", "LC_ALL", "FONTCONFIG_PATH", "FONTCONFIG_FILE"} {
		if value, exists := os.LookupEnv(name); exists {
			result = append(result, name+"="+value)
		}
	}
	for _, name := range []string{"TMPDIR", "TMP", "TEMP"} {
		result = append(result, name+"="+directory)
	}
	// On Windows environment names are case-insensitive; os/exec normalizes
	// duplicate keys, and PATH above resolves the usual mixed-case Path key.
	return result
}

func privateDirectory() (string, error) {
	parent := os.TempDir()
	// Chromium's Unix singleton socket has a short OS path limit. Respect a
	// user's temp root where possible, using a private /tmp child if too long.
	if runtime.GOOS != "windows" && len(parent) > 32 {
		parent = "/tmp"
	}
	return os.MkdirTemp(parent, "cd-chart-")
}

type limitedBuffer struct {
	bytes.Buffer
	max int
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	if len(p) > b.max-b.Len() {
		return 0, fmt.Errorf("chart output exceeds %d bytes: %w", b.max, io.ErrShortWrite)
	}
	return b.Buffer.Write(p)
}
